node -v; cat > /tmp/slug-check.mjs <<'EOF'
import { slugify } from '/private/var/folders/b_/9c_2y9gx4bx9hg3chvdwmdl00000gn/T/m10b-s4r4-BgCA0V/src/slug.ts';
const cases = [
  ['Hello World', undefined, 'hello-world'],
  ['a  b', undefined, 'a-b'],
  [' hi! ', undefined, 'hi'],
  ['Hello, World!', undefined, 'hello-world'],
  ['A--B', undefined, 'a-b'],
  ['中文标题', undefined, ''],
  ['Foo 中文 Bar', undefined, 'foo-bar'],
  ['a    b---c', undefined, 'a-b-c'],
  ['__foo__bar__', undefined, 'foo-bar'],
  ['Hello World', 11, 'hello-world'],
  ['Hello World', 8, 'hello'],
  ['Hello World', 6, 'hello'],
  ['Hello World', 5, 'hello'],
  ['hello world', 3, ''],
  ['hello world', 0, ''],
  ['hello world', -5, ''],
  ['a-b-c', 4, 'a-b'],
  ['', undefined, ''],
  ['!!!', undefined, ''],
  ['Hello World', 100, 'hello-world'],
];
let bad = 0;
for (const [t, n, want] of cases) {
  const got = n === undefined ? slugify(t) : slugify(t, n);
  const ok = got === want;
  if (!ok) bad++;
  console.log(`${ok ? 'ok  ' : 'FAIL'} slugify(${JSON.stringify(t)}${n === undefined ? '' : ', ' + n}) = ${JSON.stringify(got)}${ok ? '' : ' (want ' + JSON.stringify(want) + ')'}`);
}
// 后置不变式：截断结果不长于 maxLength、不以横线结尾、无连续横线
for (const t of ['The Quick Brown Fox Jumps', 'a  b   c', 'Hello World']) {
  for (let n = 0; n <= 30; n++) {
    const s = slugify(t, n);
    if (s.length > n || s.endsWith('-') || s.startsWith('-') || s.includes('--')) { bad++; console.log('INVARIANT FAIL', t, n, s); }
  }
}
console.log(bad === 0 ? 'ALL PASS' : `${bad} FAILURES`);
EOF
